/bin/bash -lc "npm test && node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import net from 'node:net';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createPantryServer } from './src/server.js';

const directory = await mkdtemp(join(tmpdir(), 'pantry-diagnosis-'));
const dataFile = join(directory, 'inventory.json');
const server = createPantryServer({ dataFile });
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const { port } = server.address();
const body = JSON.stringify({ item: 'Rice', kind: 'donation', quantity: 2 });

const socket = net.connect(port, '127.0.0.1');
await new Promise((resolve, reject) => {
  socket.once('connect', resolve);
  socket.once('error', reject);
});
socket.write("'`POST /api/movements HTTP/1.1'"\\r\\nHost: 127.0.0.1\\r\\nContent-Type: application/json\\r\\nContent-Length: "'${Buffer.byteLength(body)}'"\\r\\nConnection: close\\r\\n\\r\\n"'${body}`);
socket.destroy();
await new Promise((resolve) => setTimeout(resolve, 100));

let response = await fetch(`http://127.0.0.1:${port}/api/inventory`);
const afterUnseenResponse = await response.json();
assert.deepEqual(afterUnseenResponse.items.map(({ name, quantity }) => ({ name, quantity })), [{ name: '"'Rice', quantity: 2 }]);

response = await fetch("'`http://127.0.0.1:${port}/api/movements`, {
  method: '"'POST', headers: { 'content-type': 'application/json' }, body,
});
assert.equal(response.status, 200);
response = await fetch("'`http://127.0.0.1:${port}/api/inventory`);
const afterRetry = await response.json();
assert.deepEqual(afterRetry.items.map(({ name, quantity }) => ({ name, quantity })), [{ name: '"'Rice', quantity: 4 }]);

await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
await rm(directory, { recursive: true, force: true });
console.log(JSON.stringify({ afterUnseenResponse, afterRetry }, null, 2));
